import { NavLink } from "react-router-dom";
import FormatPrice from "../Helpers/FormatPrice";
import { FiArrowRight, FiCheckCircle } from "react-icons/fi";
import { motion, AnimatePresence } from "framer-motion";

const ListView = ({ products }) => {
  return (
    <motion.div layout className="flex flex-col gap-6">
      <AnimatePresence>
        {products.map((curElem, index) => {
          const { id, name, image, price, description, category, colors, stars, stock } = curElem;
          const imgUrl =
            image && image.length > 0 && image[0]?.url
              ? image[0].url
              : "https://placehold.co/400x400/1a1a1a/555?text=Product";

          return (
            <motion.div 
              className="bg-white dark:bg-[#111111] border border-black/5 dark:border-white/5 rounded-3xl overflow-hidden grid grid-cols-1 lg:grid-cols-[240px_1fr_240px] hover:shadow-xl dark:hover:border-blue-500/30 transition-all duration-300 hover:-translate-y-1 group" 
              key={id}
              initial={{ opacity: 0, y: 20 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.5, delay: index * 0.05 }}
            >
              <div className="bg-[#f5f5f7] dark:bg-[#1a1a1a] p-8 flex items-center justify-center border-b lg:border-b-0 lg:border-r border-black/5 dark:border-white/5">
                <img
                  src={imgUrl}
                  alt={name}
                  loading="lazy"
                  className="w-full h-44 object-contain transition-transform duration-500 group-hover:scale-110 mix-blend-multiply dark:mix-blend-normal"
                />
              </div>

              <div className="p-8 flex flex-col justify-between gap-4">
                <div>
                  <span className="text-blue-500 dark:text-blue-400 font-bold uppercase tracking-wider text-xs mb-2 block">{category}</span>
                  <h3 className="text-2xl font-bold tracking-tight text-black dark:text-white mb-2">{name}</h3>
                  <div className="flex items-center gap-1">
                    {[1,2,3,4,5].map(s => (
                      <span key={s} className={s <= Math.round(stars) ? "text-yellow-500 text-sm" : "text-black/10 dark:text-white/10 text-sm"}>★</span>
                    ))}
                    <span className="text-sm text-black/40 dark:text-white/40 ml-1 font-semibold">{parseFloat(stars).toFixed(1)}</span>
                  </div>
                </div>

                <p className="text-black/60 dark:text-white/60 text-base leading-relaxed line-clamp-2">
                  {description}
                </p>

                <div className="flex items-center gap-6 mt-2">
                  {stock > 0 && (
                    <span className="flex items-center text-sm font-semibold text-green-600 dark:text-green-500">
                      <FiCheckCircle className="mr-1.5" /> In Stock
                    </span>
                  )}
                  {colors && colors.length > 0 && (
                    <div className="flex gap-1.5">
                      {colors.slice(0, 4).map((c, i) => (
                        <span key={i} className="w-3.5 h-3.5 rounded-full border border-black/10 dark:border-white/10" style={{ background: c }} />
                      ))}
                    </div>
                  )}
                </div>
              </div>

              <div className="p-8 flex lg:flex-col justify-between lg:justify-center items-center gap-6 bg-black/[0.02] dark:bg-white/[0.02] border-t lg:border-t-0 lg:border-l border-black/5 dark:border-white/5">
                <div className="text-center">
                  <span className="text-3xl font-bold text-black dark:text-white tracking-tight block mb-1">
                    <FormatPrice price={price} />
                  </span>
                  <span className="text-xs text-black/40 dark:text-white/40 font-medium">Excl. taxes</span>
                </div>
                <NavLink to={`/singleproduct/${id}`}>
                  <button className="flex items-center gap-2 px-6 py-3 bg-blue-600 hover:bg-blue-700 text-white rounded-full font-semibold transition-transform hover:scale-105 active:scale-95">
                    View Detail <FiArrowRight />
                  </button>
                </NavLink>
              </div>
            </motion.div>
          );
        })}
      </AnimatePresence>
    </motion.div>
  );
};

export default ListView;