import { useFilterContext } from "../context/filter_context";
import { FiCheck } from "react-icons/fi";
import FormatPrice from "../Helpers/FormatPrice";

const FilterSection = () => {
  const {
    filters: { text, category, color, price, maxPrice, minPrice },
    updateFilterValue,
    all_products,
    clearFilters,
  } = useFilterContext();

  const getUniqueData = (data, attr) => {
    let newVal = data.map((curElem) => curElem[attr]);
    if (attr === "colors") newVal = newVal.flat();
    return ["all", ...new Set(newVal)];
  };

  const categoryData = getUniqueData(all_products, "category");
  const colorsData = getUniqueData(all_products, "colors");

  return (
    <div className="bg-white dark:bg-[#111111] p-6 rounded-3xl border border-black/5 dark:border-white/5">
      <div className="flex justify-between items-center pb-4 border-b border-black/5 dark:border-white/5 mb-4">
        <h3 className="text-xl font-bold text-black dark:text-white tracking-tight">Filters</h3>
        <button className="text-blue-600 hover:text-blue-700 text-sm font-medium" onClick={clearFilters}>
          Clear All
        </button>
      </div>

      {/* Search */}
      <div className="py-4 border-b border-black/5 dark:border-white/5 space-y-3">
        <label className="block text-xs font-semibold uppercase tracking-widest text-black/40 dark:text-white/40">Search</label>
        <form onSubmit={(e) => e.preventDefault()}>
          <input
            type="text"
            name="text"
            placeholder="Search products..."
            value={text}
            onChange={updateFilterValue}
            className="w-full px-4 py-3 bg-black/5 dark:bg-white/5 text-black dark:text-white border border-transparent focus:border-blue-500 rounded-xl outline-none transition-colors placeholder:text-black/30 dark:placeholder:text-white/30"
          />
        </form>
      </div>

      {/* Category */}
      <div className="py-4 border-b border-black/5 dark:border-white/5 space-y-3">
        <label className="block text-xs font-semibold uppercase tracking-widest text-black/40 dark:text-white/40">Category</label>
        <div className="flex flex-col gap-1">
          {categoryData.map((curElem, index) => (
            <button
              key={index}
              type="button"
              name="category"
              value={curElem}
              className={`flex items-center gap-3 px-3 py-2 rounded-xl text-sm transition-all focus:outline-none ${
                curElem === category 
                ? "bg-blue-500/10 text-blue-600 dark:bg-blue-500/20 font-semibold" 
                : "text-black/60 dark:text-white/60 hover:bg-black/5 dark:hover:bg-white/5 hover:text-black dark:hover:text-white"
              }`}
              onClick={updateFilterValue}
            >
              <span className={`w-1.5 h-1.5 rounded-full ${curElem === category ? "bg-blue-600" : "bg-black/20 dark:bg-white/20"}`} />
              <span className="capitalize">{curElem}</span>
            </button>
          ))}
        </div>
      </div>

      {/* Colors */}
      <div className="py-4 border-b border-black/5 dark:border-white/5 space-y-3">
        <label className="block text-xs font-semibold uppercase tracking-widest text-black/40 dark:text-white/40">Color</label>
        <div className="flex flex-wrap gap-2 items-center">
          {colorsData.map((curColor, index) => {
            if (curColor === "all") {
              return (
                <button
                  key={index}
                  type="button"
                  value={curColor}
                  name="color"
                  className={`px-3 py-1 rounded-full border text-xs font-medium transition-all ${
                    color === "all"
                    ? "border-blue-500 text-blue-600 bg-blue-500/10"
                    : "border-black/10 dark:border-white/10 text-black/60 dark:text-white/60 hover:border-black/30 dark:hover:border-white/30"
                  }`}
                  onClick={updateFilterValue}
                >
                  All
                </button>
              );
            }
            return (
              <button
                key={index}
                type="button"
                value={curColor}
                name="color"
                style={{ backgroundColor: curColor }}
                className={`w-7 h-7 rounded-full border-2 flex items-center justify-center shadow-inner transition-transform hover:scale-110 ${
                  color === curColor 
                  ? "border-blue-500 shadow-[0_0_0_2px_rgba(59,130,246,0.3)]" 
                  : "border-transparent"
                }`}
                onClick={updateFilterValue}
                title={curColor}
              >
                {color === curColor && (
                  <FiCheck
                    className={curColor === "#ffffff" || curColor === "#f5f5f7" ? "text-black" : "text-white"}
                    size={14}
                  />
                )}
              </button>
            );
          })}
        </div>
      </div>

      {/* Price */}
      <div className="py-4 mt-2">
        <div className="flex justify-between items-center mb-3">
          <label className="block text-xs font-semibold uppercase tracking-widest text-black/40 dark:text-white/40">Max Price</label>
          <span className="text-sm font-bold text-black dark:text-white"><FormatPrice price={price} /></span>
        </div>
        <input
          type="range"
          name="price"
          min={minPrice}
          max={maxPrice}
          value={price}
          onChange={updateFilterValue}
          className="w-full h-1 bg-black/10 dark:bg-white/10 rounded-full appearance-none cursor-pointer accent-blue-600"
        />
        <div className="flex justify-between mt-2 text-xs text-black/40 dark:text-white/40 font-medium">
          <span><FormatPrice price={minPrice} /></span>
          <span><FormatPrice price={maxPrice} /></span>
        </div>
      </div>
    </div>
  );
};

export default FilterSection;