import { createContext, useContext, useEffect, useReducer } from "react";
import reducer from "../reducer/productReducer";

const AppContext = createContext();

const API_URL = "https://dummyjson.com/products/search?q=apple";

const initialState = {
  isLoading: false,
  isError: false,
  products: [],
  featureProducts: [],
  isSingleLoading: false,
  singleProduct: {},
};

// Map DummyJSON products to Gearlogy style
const mapProductData = (product) => {
  // Enhancing the dummy data visual quality with generic high-res place holders 
  // or direct matches if possible to keep the site looking "premium"
  const cdnLinks = {
    'Apple MacBook Pro 14 Inch Space Grey': 'https://store.storeimages.cdn-apple.com/4982/as-images.apple.com/is/mbp14-spacegray-select-202310?wid=904&hei=840&fmt=jpeg&qlt=90&.v=1697230830200',
    'Apple Airpods': 'https://store.storeimages.cdn-apple.com/4982/as-images.apple.com/is/MQD83?wid=1144&hei=1144&fmt=jpeg&qlt=90&.v=1660803972361',
    'Apple AirPods Max Silver': 'https://store.storeimages.cdn-apple.com/4982/as-images.apple.com/is/airpods-max-select-spacegray-202011?wid=904&hei=840&fmt=jpeg&qlt=90&.v=1604021221000',
    'Apple Watch Series 4 Gold': 'https://store.storeimages.cdn-apple.com/4982/as-images.apple.com/is/watch-s9-alum-midnight-nc-cell-202309_VW_PF_WF_CO?wid=2000&hei=2000&fmt=jpeg&qlt=90&.v=1693259972338',
    'iPad Mini 2021 Starlight': 'https://store.storeimages.cdn-apple.com/4982/as-images.apple.com/is/ipad-air-storage-select-202207-blue?wid=2560&hei=1440&fmt=p-jpg&qlt=95&.v=1655246736173'
  };

  const imageMap = cdnLinks[product.title] ? [{ url: cdnLinks[product.title] }] : [{ url: product.thumbnail }];
  
  return {
    id: product.id.toString(),
    name: product.title,
    company: product.brand || "Apple",
    price: product.price * 8000, 
    description: product.description,
    category: product.category,
    featured: product.rating > 4.5,
    stock: product.stock,
    stars: product.rating,
    reviews: product.reviews?.length || Math.floor(Math.random() * 500),
    colors: ["#1d1d1f", "#f5f5f7", "#86868b"],
    image: imageMap,
    brand: product.brand
  };
};

const AppProvider = ({ children }) => {
  const [state, dispatch] = useReducer(reducer, initialState);

  const getProducts = async () => {
    dispatch({ type: "SET_LOADING" });
    try {
      const res = await fetch(API_URL);
      const data = await res.json();
      
      const mappedProducts = data.products
        .filter(p => p.category !== "groceries")
        .map(mapProductData);

      dispatch({ type: "SET_API_DATA", payload: mappedProducts });
    } catch (error) {
      dispatch({ type: "API_ERROR" });
    }
  };

  const getSingleProduct = async (id) => {
    dispatch({ type: "SET_SINGLE_LOADING" });
    try {
      const res = await fetch(`https://dummyjson.com/products/${id}`);
      const product = await res.json();
      
      if (product) {
        dispatch({ type: "SET_SINGLE_PRODUCT", payload: mapProductData(product) });
      } else {
        dispatch({ type: "SET_SINGLE_ERROR" });
      }
    } catch (error) {
      dispatch({ type: "SET_SINGLE_ERROR" });
    }
  };

  useEffect(() => {
    getProducts();
  }, []);

  return (
    <AppContext.Provider value={{ ...state, getSingleProduct }}>
      {children}
    </AppContext.Provider>
  );
};

const useProductContext = () => {
  return useContext(AppContext);
};

export { AppProvider, AppContext, useProductContext };