import React from "react";
import FormatPrice from "../Helpers/FormatPrice";
import { FiTrash2, FiMinus, FiPlus } from "react-icons/fi";
import { useCartContext } from "../context/cart_context";

const CartItem = ({ id, name, image, color, price, amount }) => {
  const { removeItem, setDecrease, setIncrement } = useCartContext();

  return (
    <div className="grid grid-cols-1 lg:grid-cols-[auto_1fr_auto] gap-6 items-center p-6 bg-white dark:bg-[#111111] border border-black/5 dark:border-white/5 rounded-3xl group transition-all hover:shadow-md dark:hover:border-blue-500/30">
      
      <div className="flex items-center gap-6">
        <div className="w-24 h-24 bg-[#f5f5f7] dark:bg-[#1a1a1a] rounded-2xl flex items-center justify-center p-3 border border-black/5 dark:border-white/5 shrink-0">
          <img
            src={image}
            alt={name}
            className="w-full h-full object-contain mix-blend-multiply dark:mix-blend-normal transform transition-transform group-hover:scale-105"
            onError={(e) => {
              e.target.src = "https://placehold.co/80x80/111111/444?text=Item";
            }}
          />
        </div>
        
        <div className="flex flex-col gap-1.5">
          <p className="text-[17px] font-semibold text-black dark:text-white tracking-tight line-clamp-2 leading-tight">
            {name}
          </p>
          {color && (
            <div className="flex items-center gap-2 mt-1">
              <span className="w-3.5 h-3.5 rounded-full border border-black/20 dark:border-white/20" style={{ backgroundColor: color }} />
              <span className="text-sm font-medium text-black/50 dark:text-white/50">{color}</span>
            </div>
          )}
          <div className="text-base font-medium text-black/50 dark:text-white/50 lg:hidden mt-2">
            <FormatPrice price={price} />
          </div>
        </div>
      </div>

      <div className="hidden lg:flex flex-col gap-1 items-center justify-center">
        <span className="text-lg font-medium text-black/50 dark:text-white/50"><FormatPrice price={price} /></span>
      </div>

      <div className="flex items-center justify-between lg:justify-end gap-6 w-full lg:w-auto mt-4 lg:mt-0 pt-4 lg:pt-0 border-t border-black/5 dark:border-white/5 lg:border-none">
        
        <div className="flex items-center gap-4 bg-[#f5f5f7] dark:bg-[#1a1a1a] rounded-full p-1 border border-black/5 dark:border-white/5">
          <button
            className="w-8 h-8 flex items-center justify-center rounded-full text-black/60 dark:text-white/60 hover:bg-black/5 dark:hover:bg-white/5 hover:text-black dark:hover:text-white cursor-pointer disabled:opacity-30 transition-colors"
            onClick={() => setDecrease(id)}
            disabled={amount <= 1}
          >
            <FiMinus size={14} />
          </button>
          <span className="w-6 text-center font-bold text-black dark:text-white text-[15px]">{amount}</span>
          <button 
            className="w-8 h-8 flex items-center justify-center rounded-full text-black/60 dark:text-white/60 hover:bg-black/5 dark:hover:bg-white/5 hover:text-black dark:hover:text-white cursor-pointer transition-colors"
            onClick={() => setIncrement(id)}
          >
            <FiPlus size={14} />
          </button>
        </div>

        <div className="flex items-center gap-6">
          <div className="text-xl font-bold text-black dark:text-white tracking-tight">
            <FormatPrice price={price * amount} />
          </div>

          <button
            className="w-10 h-10 flex items-center justify-center rounded-full text-black/40 dark:text-white/40 hover:bg-red-50 hover:text-red-500 hover:border hover:border-red-500/20 transition-all cursor-pointer"
            onClick={() => removeItem(id)}
             title="Remove"
          >
            <FiTrash2 size={18} />
          </button>
        </div>

      </div>

    </div>
  );
};

export default CartItem;