import { useEffect, useState, useRef } from "react";
import styled from "styled-components";
import { useParams, NavLink } from "react-router-dom";
import { useProductContext } from "./context/productcontext";
import FormatPrice from "./Helpers/FormatPrice";
import { MdSecurity } from "react-icons/md";
import { TbTruckDelivery, TbRefresh } from "react-icons/tb";
import { FiShoppingCart, FiHeart, FiCheck, FiArrowRight, FiChevronDown } from "react-icons/fi";
import { useCartContext } from "./context/cart_context";
import { motion, useScroll, useTransform, AnimatePresence } from "framer-motion";

const SingleProduct = () => {
  const { getSingleProduct, isSingleLoading, singleProduct } = useProductContext();
  const { addToCart } = useCartContext();
  const { id } = useParams();

  const [selectedColor, setSelectedColor] = useState(null);
  const [amount, setAmount] = useState(1);
  const [activeImg, setActiveImg] = useState(0);
  const [addedToCart, setAddedToCart] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");

  const { name, price, description, stock, image, colors } = singleProduct;

  const containerRef = useRef(null);
  const { scrollYProgress } = useScroll({ target: containerRef, offset: ["start end", "end start"] });
  const heroScale = useTransform(scrollYProgress, [0, 0.3], [1, 1.15]);
  const heroOpacity = useTransform(scrollYProgress, [0, 0.2], [1, 0]);

  useEffect(() => {
    getSingleProduct(id);
    window.scrollTo(0, 0);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [id]);

  useEffect(() => {
    if (colors && colors.length > 0 && !selectedColor) {
      setSelectedColor(colors[0]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [colors]);

  const handleAddToCart = () => {
    addToCart(id, selectedColor, amount, singleProduct);
    setAddedToCart(true);
    setTimeout(() => setAddedToCart(false), 2000);
  };

  if (isSingleLoading || !name) {
    return (
      <LoadingWrap>
        <div className="ld-spinner" />
      </LoadingWrap>
    );
  }

  const imgs = image && image.length > 0
    ? image.filter((i) => i?.url && i.url.startsWith("http"))
    : [{ url: "https://placehold.co/600x600/111111/444?text=Product" }];

  const safePrice = typeof price === "number" ? price : 0;

  return (
    <Wrapper ref={containerRef}>
      {/* Sticky Top Nav */}
      <div className="sticky-nav">
        <div className="sn-inner">
          <div className="sn-left">
            <h2>{name}</h2>
          </div>
          <div className="sn-center">
            <button className={activeTab === "overview" ? "active" : ""} onClick={() => { setActiveTab("overview"); window.scrollTo({top:0, behavior:'smooth'})}}>Overview</button>
            <button className={activeTab === "specs" ? "active" : ""} onClick={() => setActiveTab("specs")}>Tech Specs</button>
            <button className={activeTab === "compare" ? "active" : ""} onClick={() => setActiveTab("compare")}>Compare</button>
          </div>
          <div className="sn-right">
            <span className="sn-price"><FormatPrice price={safePrice} /></span>
            <button className="buy-btn" onClick={() => window.scrollTo({top: document.body.scrollHeight, behavior: 'smooth'})}>Buy</button>
          </div>
        </div>
      </div>

      {activeTab === "overview" && (
        <motion.div initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} className="tab-pane">
          {/* Cinematic Hero */}
          <div className="hero-section">
            <motion.div style={{ scale: heroScale, opacity: heroOpacity }} className="hero-img-bg">
               <img src={imgs[0]?.url} alt={name} className="hero-main-img" onError={(e) => { e.target.src = "https://placehold.co/600x600/111111/444"; }}/>
            </motion.div>
            <div className="hero-content">
              <motion.h1 
                initial={{y:30, opacity:0}}
                animate={{y:0, opacity:1}}
                transition={{duration: 1, ease: "easeOut"}}
              >
                {name}
              </motion.h1>
              <motion.p
                initial={{y:30, opacity:0}}
                animate={{y:0, opacity:1}}
                transition={{duration: 1, delay: 0.2, ease: "easeOut"}}
                className="hero-tagline"
              >
                {description.split('.')[0]}.
              </motion.p>
            </div>
            <div className="scroll-indicator">
              <FiChevronDown />
            </div>
          </div>

          {/* Scrolling Features */}
          <div className="features-scroll-section">
             <div className="fs-grid">
               <motion.div 
                 initial={{opacity: 0, x: -50}} whileInView={{opacity: 1, x: 0}} viewport={{once: true, margin: "-20%"}}
                 transition={{duration: 0.8}}
                 className="fs-text"
               >
                 <h2>Pro-level Performance.</h2>
                 <p>{description}</p>
               </motion.div>
               <motion.div 
                 initial={{opacity: 0, x: 50}} whileInView={{opacity: 1, x: 0}} viewport={{once: true, margin: "-20%"}}
                 transition={{duration: 0.8}}
                 className="fs-media"
               >
                 <img src={imgs.length > 1 ? imgs[1].url : imgs[0].url} alt="Feature" />
               </motion.div>
             </div>
          </div>
        </motion.div>
      )}

      {/* Buy Bar Section (Specs/Purchase) */}
      <div className="purchase-section" id="purchase">
        <div className="purchase-inner">
          {/* Gallery */}
          <div className="gallery-stick">
            <AnimatePresence mode="wait">
              <motion.img
                key={activeImg}
                initial={{ opacity: 0, scale: 0.95 }}
                animate={{ opacity: 1, scale: 1 }}
                exit={{ opacity: 0, scale: 0.95 }}
                transition={{ duration: 0.3 }}
                src={imgs[activeImg]?.url}
                alt={name}
                className="main-view"
              />
            </AnimatePresence>
            <div className="thumb-row">
              {imgs.slice(0, 5).map((img, i) => (
                <button
                  key={i}
                  className={`thumb ${activeImg === i ? "active" : ""}`}
                  onClick={() => setActiveImg(i)}
                >
                  <img src={img.url} alt={`view ${i}`} />
                </button>
              ))}
            </div>
          </div>

          {/* Purchase Controls */}
          <div className="buy-panel">
            <div className="bp-header">
              <span className="bp-cat">New</span>
              <h3>Buy {name}</h3>
              <div className="bp-price">
                <FormatPrice price={safePrice} />
                <span className="bp-tax">Incl. of all taxes</span>
              </div>
            </div>

            {/* Colors */}
            {colors && colors.length > 0 && (
              <div className="bp-card">
                <span className="bp-label">Finish. <span>Pick your favorite.</span></span>
                <div className="bp-colors">
                  {colors.map((c, i) => (
                    <button
                      key={i}
                      className={`color-btn ${selectedColor === c ? "active" : ""}`}
                      onClick={() => setSelectedColor(c)}
                    >
                      <span className="color-swatch" style={{ background: c }}></span>
                      <span className="color-name">{c}</span>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Quantity & Cart */}
            <div className="bp-card actions-card">
              <div className="qty-row">
                <span className="bp-label">Quantity</span>
                <div className="qty-pill">
                  <button onClick={() => setAmount((a) => Math.max(1, a - 1))} disabled={amount <= 1}>−</button>
                  <span>{amount}</span>
                  <button onClick={() => setAmount((a) => Math.min(stock || 10, a + 1))} disabled={amount >= (stock || 10)}>+</button>
                </div>
              </div>

              <div className="btn-row">
                {stock > 0 ? (
                  <button className="primary-add" onClick={handleAddToCart}>
                    {addedToCart ? <><FiCheck /> Added to Bag</> : <><FiShoppingCart /> Add to Bag</>}
                  </button>
                ) : (
                  <button className="primary-add disabled" disabled>Out of Stock</button>
                )}
                <button className="wish-btn"><FiHeart /></button>
              </div>
            </div>

            <div className="delivery-info">
              <div className="di-item"><TbTruckDelivery /> <span>Free Delivery</span></div>
              <div className="di-item"><TbRefresh /> <span>30-Day Returns</span></div>
              <div className="di-item"><MdSecurity /> <span>Secure Checkout</span></div>
            </div>
          </div>
        </div>
      </div>
    </Wrapper>
  );
};

const LoadingWrap = styled.div`
  height: 100vh; background: #000; display: flex; align-items: center; justify-content: center;
  .ld-spinner { width: 40px; height: 40px; border: 3px solid rgba(255,255,255,0.1); border-top-color: #0071e3; border-radius: 50%; animation: spin 1s linear infinite; }
  @keyframes spin { to { transform: rotate(360deg); } }
`;

const Wrapper = styled.div`
  background: #000;
  min-height: 100vh;
  color: #fff;

  .sticky-nav {
    position: sticky;
    top: 6rem; /* below main header */
    z-index: 100;
    background: rgba(0,0,0,0.8);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid rgba(255,255,255,0.05);

    .sn-inner {
      max-width: 120rem;
      margin: 0 auto;
      height: 5.6rem;
      padding: 0 4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .sn-left h2 { font-size: 1.6rem; font-weight: 600; mragin: 0; }

    .sn-center {
      display: flex; gap: 2rem;
      button {
        background: none; border: none; font-size: 1.3rem; color: rgba(255,255,255,0.6);
        cursor: pointer; transition: color 0.2s;
        &.active, &:hover { color: #fff; }
      }
    }

    .sn-right {
      display: flex; align-items: center; gap: 2rem;
      .sn-price { font-size: 1.3rem; font-weight: 500; }
      .buy-btn {
        background: #0071e3; color: #fff; border: none; padding: 0.6rem 1.4rem;
        border-radius: 2rem; font-size: 1.2rem; font-weight: 600; cursor: pointer;
        &:hover { background: #0077ed; }
      }
    }
  }

  .hero-section {
    position: relative;
    height: calc(100vh - 11.6rem);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    overflow: hidden;

    .hero-img-bg {
      position: absolute; inset: 0; display: flex; align-items: center; justify-content: center;
      .hero-main-img { width: 70%; height: 70%; object-fit: contain; filter: brightness(0.9); }
    }

    .hero-content {
      position: relative; z-index: 2; text-align: center;
      h1 { font-size: 6rem; font-weight: 700; letter-spacing: -0.04em; margin-bottom: 1.6rem; }
      .hero-tagline { font-size: 2.2rem; color: rgba(255,255,255,0.6); max-width: 50rem; }
    }

    .scroll-indicator {
      position: absolute; bottom: 4rem; font-size: 2.4rem; color: rgba(255,255,255,0.4);
      animation: bounce 2s infinite;
    }
    @keyframes bounce { 0%, 20%, 50%, 80%, 100% {transform: translateY(0);} 40% {transform: translateY(-10px);} 60% {transform: translateY(-5px);} }
  }

  .features-scroll-section {
    padding: 10rem 4rem;
    max-width: 140rem;
    margin: 0 auto;

    .fs-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8rem; align-items: center; }
    .fs-text h2 { font-size: 4.8rem; font-weight: 700; margin-bottom: 2.4rem; letter-spacing: -0.04em; }
    .fs-text p { font-size: 1.8rem; color: rgba(255,255,255,0.5); line-height: 1.6; }
    .fs-media img { width: 100%; border-radius: 2rem; border: 1px solid rgba(255,255,255,0.05); }
  }

  .purchase-section {
    background: #0a0a0a;
    padding: 8rem 4rem;
    border-top: 1px solid rgba(255,255,255,0.05);
  }

  .purchase-inner {
    max-width: 120rem; margin: 0 auto;
    display: grid; grid-template-columns: 1.2fr 1fr; gap: 8rem; align-items: flex-start;
  }

  .gallery-stick {
    position: sticky; top: 16rem;
    .main-view { width: 100%; height: 50rem; object-fit: contain; background: #111; border-radius: 2.4rem; padding: 4rem; border: 1px solid rgba(255,255,255,0.06); margin-bottom: 2rem; }
    .thumb-row { display: flex; gap: 1.2rem; justify-content: center; }
    .thumb { width: 7rem; height: 7rem; background: #111; border: 2px solid transparent; border-radius: 1.2rem; padding: 0.8rem; cursor: pointer; transition: all 0.2s;
             img { width: 100%; height: 100%; object-fit: contain; }
             &.active { border-color: #0071e3; }
             &:hover { border-color: rgba(255,255,255,0.2); }
    }
  }

  .buy-panel {
    display: flex; flex-direction: column; gap: 3rem;

    .bp-header {
      .bp-cat { color: #ff9f0a; font-weight: 600; font-size: 1.3rem; text-transform: uppercase; letter-spacing: 0.1em; display: inline-block; margin-bottom: 1rem; }
      h3 { font-size: 4rem; font-weight: 700; letter-spacing: -0.04em; margin-bottom: 1.6rem; }
      .bp-price { font-size: 2.4rem; font-weight: 700; display: flex; flex-direction: column; gap: 0.4rem; }
      .bp-tax { font-size: 1.2rem; color: rgba(255,255,255,0.4); font-weight: 400; }
    }

    .bp-card { border-top: 1px solid rgba(255,255,255,0.08); padding-top: 3rem; }
    .bp-label { font-size: 1.8rem; font-weight: 600; display: block; margin-bottom: 1.6rem;
                span { color: rgba(255,255,255,0.5); font-weight: 400; font-size: 1.5rem; margin-left: 0.8rem; } }

    .bp-colors {
      display: grid; grid-template-columns: 1fr 1fr; gap: 1.2rem;
      .color-btn {
        background: #111; border: 1px solid rgba(255,255,255,0.1); border-radius: 1.2rem; padding: 1.6rem;
        display: flex; flex-direction: column; align-items: center; gap: 1rem; cursor: pointer; transition: all 0.2s;
        &:hover { border-color: rgba(255,255,255,0.3); background: #161616; }
        &.active { border-color: #0071e3; box-shadow: 0 0 0 1px #0071e3; }
      }
      .color-swatch { width: 3rem; height: 3rem; border-radius: 50%; border: 1px solid rgba(255,255,255,0.2); }
      .color-name { font-size: 1.4rem; color: #fff; font-weight: 500; }
    }

    .actions-card {
      .qty-row { display: flex; justify-content: space-between; align-items: center; margin-bottom: 2.4rem; .bp-label { margin-bottom: 0; } }
      .qty-pill { display: flex; align-items: center; background: #111; border: 1px solid rgba(255,255,255,0.1); border-radius: 3rem; padding: 0.4rem;
                  button { width: 3.6rem; height: 3.6rem; border-radius: 50%; background: transparent; border: none; color: #fff; font-size: 1.8rem; cursor: pointer; &:hover { background: rgba(255,255,255,0.05); } &:disabled { opacity: 0.3; } }
                  span { width: 3rem; text-align: center; font-size: 1.5rem; font-weight: 600; } }

      .btn-row { display: flex; gap: 1.2rem; }
      .primary-add { flex: 1; background: #0071e3; color: #fff; border: none; padding: 1.6rem; border-radius: 1.2rem; font-size: 1.6rem; font-weight: 600; display: flex; align-items: center; justify-content: center; gap: 1rem; cursor: pointer; transition: all 0.2s;
                     &:hover { background: #0077ed; transform: translateY(-1px); }
                     &.disabled { background: #222; color: #666; cursor: not-allowed; } }
      .wish-btn { width: 5.4rem; background: #111; border: 1px solid rgba(255,255,255,0.1); border-radius: 1.2rem; color: #fff; font-size: 2rem; display: flex; align-items: center; justify-content: center; cursor: pointer; &:hover { border-color: #ff375f; color: #ff375f; } }
    }

    .delivery-info { display: flex; flex-direction: column; gap: 1.6rem; background: #111; border-radius: 1.6rem; padding: 2rem;
                     .di-item { display: flex; align-items: center; gap: 1.2rem; color: rgba(255,255,255,0.7); font-size: 1.4rem; font-weight: 500; svg { font-size: 2rem; color: #0071e3; } } }
  }

  @media (max-width: 1024px) {
    .purchase-inner { grid-template-columns: 1fr; }
    .gallery-stick { position: static; }
    .fs-grid { grid-template-columns: 1fr !important; text-align: center; }
  }
`;

export default SingleProduct;