import React from "react";
import { NavLink } from "react-router-dom";
import FormatPrice from "../Helpers/FormatPrice";
import { motion } from "framer-motion";

const Product = ({ id, name, image, price, category, stars, reviews, colors }) => {
  const imgUrl =
    image && image.length > 0 && image[0]?.url
      ? image[0].url
      : `https://placehold.co/400x400/111111/555555?text=Product`;

  return (
    <NavLink to={`/singleproduct/${id}`} className="block">
      <motion.div
        whileHover={{ y: -8 }}
        transition={{ type: "spring", stiffness: 300, damping: 20 }}
        className="group flex flex-col h-full bg-[#f5f5f7]/50 dark:bg-white/[0.03] backdrop-blur-md rounded-[2.4rem] overflow-hidden border border-black/5 dark:border-white/5 hover:border-blue-500/40 dark:hover:border-blue-400/40 transition-colors duration-300 relative w-full"
      >
        <div className="relative h-60 flex items-center justify-center p-8 bg-white dark:bg-[#111111] border-b border-black/5 dark:border-white/5 overflow-hidden">
          <img
            src={imgUrl}
            alt={name}
            loading="lazy"
            className="max-w-[85%] max-h-44 object-contain z-10 transition-transform duration-700 ease-out group-hover:scale-110 mix-blend-multiply dark:mix-blend-normal"
            onError={(e) => {
              e.target.src = `https://placehold.co/400x400/111111/555555?text=Product`;
            }}
          />
          {category && (
            <span className="absolute top-4 left-4 bg-black/5 dark:bg-white/10 backdrop-blur-lg border border-black/10 dark:border-white/10 px-3 py-1 rounded-full text-xs font-semibold text-black/80 dark:text-white/80 capitalize z-20">
              {category}
            </span>
          )}
        </div>

        <div className="flex flex-col flex-1 p-6 gap-4">
          <div className="flex flex-col gap-1.5">
            <h3 className="text-lg font-semibold text-black dark:text-white tracking-tight leading-snug line-clamp-2">
              {name}
            </h3>
            <span className="text-base text-black/50 dark:text-white/50 font-medium">
              <FormatPrice price={price} />
            </span>
          </div>

          <div className="pt-4 border-t border-black/5 dark:border-white/5 flex flex-wrap justify-between items-center mt-auto gap-2">
            <div className="flex items-center gap-2">
              {colors && colors.slice(0, 4).map((c, i) => (
                <span
                  key={i}
                  className="w-3.5 h-3.5 rounded-full border border-black/20 dark:border-white/20 hover:scale-125 transition-transform"
                  style={{ backgroundColor: c }}
                  title={c}
                />
              ))}
            </div>
            
            <div className="flex items-center gap-1 bg-black/5 dark:bg-white/5 px-2.5 py-1 rounded-lg">
              <span className="text-yellow-500 text-sm">★</span>
              <span className="text-sm font-semibold text-black dark:text-white">{parseFloat(stars || 4.2).toFixed(1)}</span>
            </div>
          </div>
        </div>
      </motion.div>
    </NavLink>
  );
};

export default Product;