import React, { useState, useEffect } from "react";
import { NavLink } from "react-router-dom";
import { useCartContext } from "../context/cart_context";
import { motion, AnimatePresence } from "framer-motion";
import { FiShoppingBag, FiMenu, FiX, FiSearch, FiSun, FiMoon } from "react-icons/fi";

const Header = ({ toggleTheme, themeMode }) => {
  const [menuOpen, setMenuOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);
  const { total_item } = useCartContext();

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 10);
    window.addEventListener("scroll", handleScroll);
    return () => window.removeEventListener("scroll", handleScroll);
  }, []);

  const navLinks = [
    { to: "/products", label: "Store" },
    { to: "/products", label: "Mac" },
    { to: "/products", label: "iPad" },
    { to: "/products", label: "iPhone" },
    { to: "/products", label: "Watch" },
    { to: "/products", label: "Vision" },
    { to: "/products", label: "AirPods" },
    { to: "/about", label: "About" },
  ];

  return (
    <>
      <header
        className={`fixed top-0 left-0 w-full z-50 transition-all duration-500 ease-in-out ${
          scrolled
            ? "bg-white/80 dark:bg-black/80 backdrop-blur-md border-b border-black/5 dark:border-white/5"
            : "bg-transparent"
        }`}
      >
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex justify-between items-center h-12 md:h-14">
            
            {/* Logo */}
            <div className="flex-shrink-0 flex items-center">
              <NavLink to="/" onClick={() => setMenuOpen(false)}>
                <svg viewBox="0 0 16 16" className="w-4 h-4 md:w-5 md:h-5 fill-current text-black dark:text-white hover:opacity-75 transition-opacity">
                  <path d="M12.986 11.53c-.021.062-2.122 7.218-5.234 7.218-1.55 0-2.023-.972-3.8-.972-1.782 0-2.316.972-3.774.972-3.14 0-5.32-7.46-5.32-11.233 0-4.083 2.656-6.223 5.348-6.223 2.012 0 3.235 1.258 4.796 1.258 1.488 0 2.476-1.196 4.67-1.196 1.478 0 3.636.562 4.962 2.502-4.148 2.053-3.415 7.42.352 8.674zM9.404.149c-.672.827-1.144 2.003-.996 3.144 1.157.082 2.373-.615 3.013-1.442.593-.767 1.134-1.956.963-3.085-1.071-.06-2.332.55-2.98 1.383z"/>
                </svg>
              </NavLink>
            </div>

            {/* Desktop Navigation */}
            <nav className="hidden md:flex space-x-8">
              {navLinks.map((link, idx) => (
                <NavLink
                  key={idx}
                  to={link.to}
                  className="text-xs md:text-sm text-black/80 dark:text-white/80 hover:text-black dark:hover:text-white transition-colors duration-200 antialiased"
                >
                  {link.label}
                </NavLink>
              ))}
            </nav>

            {/* Right Actions */}
            <div className="flex items-center space-x-4 md:space-x-6">
              <button className="text-black/80 dark:text-white/80 hover:text-black dark:hover:text-white">
                <FiSearch className="w-4 h-4 md:w-5 md:h-5" />
              </button>
              
              <NavLink to="/cart" className="relative text-black/80 dark:text-white/80 hover:text-black dark:hover:text-white group">
                <FiShoppingBag className="w-4 h-4 md:w-5 md:h-5" />
                {total_item > 0 && (
                  <span className="absolute -top-1 -right-2 bg-blue-500 text-white text-[10px] font-bold w-4 h-4 flex items-center justify-center rounded-full border-[1.5px] border-white dark:border-black group-hover:bg-blue-600 transition-colors">
                    {total_item}
                  </span>
                )}
              </NavLink>

              {/* Theme Toggle */}
              <button onClick={toggleTheme} className="text-black/80 dark:text-white/80 hover:text-black dark:hover:text-white transition-all">
                {themeMode === 'dark' ? <FiSun className="w-4 h-4 md:w-5 md:h-5" /> : <FiMoon className="w-4 h-4 md:w-5 md:h-5" />}
              </button>
              
              {/* Mobile menu button */}
              <button
                className="md:hidden text-black dark:text-white p-1"
                onClick={() => setMenuOpen(!menuOpen)}
              >
                {menuOpen ? <FiX className="w-5 h-5" /> : <FiMenu className="w-5 h-5" />}
              </button>
            </div>
          </div>
        </div>
      </header>

      {/* Mobile Drawer Navigation */}
      <AnimatePresence>
        {menuOpen && (
          <motion.div
            initial={{ opacity: 0, y: -20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -20 }}
            transition={{ duration: 0.3 }}
            className="fixed inset-0 top-12 z-40 bg-white dark:bg-black w-full overflow-y-auto"
          >
            <div className="px-6 py-4 flex flex-col space-y-6">
              {navLinks.map((link, idx) => (
                <NavLink
                  key={idx}
                  to={link.to}
                  onClick={() => setMenuOpen(false)}
                  className="text-2xl font-semibold text-black dark:text-white border-b border-black/10 dark:border-white/10 pb-4"
                >
                  {link.label}
                </NavLink>
              ))}
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

export default Header;